The Tower of Hanoi is a mathematical puzzle with three poles and stacked disks of different sizes. The goal is to move all disks from the source pole to the destination pole using an auxiliary pole, following two rules:Only one disk can be moved at a time.A larger disk cannot be placed on a smaller one.We've already discussed a recursive solution for the Tower of Hanoi. We have also seen that for n disks, a total of  2n – 1 moves are required. Iterative Algorithm: 1. Calculate the total number of moves required i.e. "pow(2, n) - 1" here n is number of disks.2. If number of disks (i.e. n) is even then interchange destination pole and auxiliary pole.3. for i = 1 to total number of moves if i%3 == 1: legal movement of top disk between source pole and destination poleif i%3 == 2: legal movement of top disk between source pole and auxiliary pole    if i%3 == 0: legal movement of top disk between auxiliary pole and destination pole Example: Let us understand with a simple example with 3 disks:After all iterations, the destination pole holds the disks in order of size. Each time a disk (other than the smallest) is moved, the next move must involve the smallest disk, as it remains on top of the spare pole with no other options available.
            C++

    #include <bits/stdc++.h>
using namespace std;

char rod[] = {'S', 'A', 'D'};
vector<stack<int>> stacks(3);

void moveDisk(int a, int b)
{
    if (stacks[b].empty() || (!stacks[a].empty() && stacks[a].top() < stacks[b].top()))
    {
        cout << "Move disk " << stacks[a].top() << " from rod " << rod[a] << " to rod " << rod[b] << "\n";
        stacks[b].push(stacks[a].top());
        stacks[a].pop();
    }
    else
        moveDisk(b, a);
}

void towerOfHanoi(int n)
{
    cout << "Tower of Hanoi for " << n << " disks:\n";

    int src = 0, aux = 1, dest = 2;
    for (int i = n; i > 0; i--)
        stacks[src].push(i);

    int totalMoves = (1 << n) - 1;
    if (n % 2 == 0)
        swap(aux, dest);

    for (int i = 1; i <= totalMoves; i++)
    {
        if (i % 3 == 0)
            moveDisk(aux, dest);
        else if (i % 3 == 1)
            moveDisk(src, dest);
        else
            moveDisk(src, aux);
    }
}

int main()
{
    int n = 3; // number of disks
    towerOfHanoi(n);
    return 0;
}


            Java

    import java.util.Stack;

public class GfG {
    static char[] rod = { 'S', 'A', 'D' };
    static Stack<Integer>[] stacks = new Stack[3];

    static
    {
        for (int i = 0; i < 3; i++) {
            stacks[i] = new Stack<>();
        }
    }

    static void moveDisk(int a, int b)
    {
        if (stacks[b].isEmpty()
            || (!stacks[a].isEmpty()
                && stacks[a].peek() < stacks[b].peek())) {
            System.out.println("Move disk "
                               + stacks[a].peek()
                               + " from rod " + rod[a]
                               + " to rod " + rod[b]);
            stacks[b].push(stacks[a].pop());
        }
        else {
            moveDisk(b, a);
        }
    }

    static void towerOfHanoi(int n)
    {
        System.out.println("Tower of Hanoi for " + n
                           + " disks:");

        int src = 0, aux = 1, dest = 2;
        for (int i = n; i > 0; i--) {
            stacks[src].push(i);
        }

        int totalMoves = (1 << n) - 1;
        if (n % 2 == 0) {
            int temp = aux;
            aux = dest;
            dest = temp;
        }

        for (int i = 1; i <= totalMoves; i++) {
            if (i % 3 == 0)
                moveDisk(aux, dest);
            else if (i % 3 == 1)
                moveDisk(src, dest);
            else
                moveDisk(src, aux);
        }
    }

    public static void main(String[] args)
    {
        int n = 3; // number of disks
        towerOfHanoi(n);
    }
}


